<?php
namespace Tests\Feature;
use App\Models\User;
use Database\Seeders\DatabaseSeeder;
use Illuminate\Foundation\Testing\RefreshDatabase;
use Illuminate\Support\Facades\DB;
use Tests\TestCase;
class StudentAttendanceTest extends TestCase
{
 use RefreshDatabase;
 protected function beforeRefreshingDatabase():void{if(!str_ends_with((string)config('database.connections.mysql.database'),'_test'))throw new \RuntimeException('Dedicated test DB required.');}
 protected function setUp():void{parent::setUp();\Carbon\Carbon::setTestNow('2026-10-17 09:00:00');\Carbon\CarbonImmutable::setTestNow('2026-10-17 09:00:00');}
 protected function tearDown():void{\Carbon\Carbon::setTestNow();\Carbon\CarbonImmutable::setTestNow();parent::tearDown();}
 private function fixture(string $code='A',string $role='owner'):array {
  if(!DB::table('roles')->exists())$this->seed(DatabaseSeeder::class);$sid=DB::table('schools')->insertGetId(['name'=>'Attendance '.$code,'code'=>$code,'status'=>'active','timezone'=>'Asia/Karachi','currency'=>'PKR']);$cid=DB::table('campuses')->insertGetId(['school_id'=>$sid,'name'=>'Main','code'=>'MAIN','status'=>'active']);$user=User::factory()->create();$mid=DB::table('school_memberships')->insertGetId(['school_id'=>$sid,'user_id'=>$user->id,'status'=>'active']);$rid=DB::table('roles')->where('name',$role)->value('id');DB::table('membership_roles')->insert(['school_id'=>$sid,'membership_id'=>$mid,'role_id'=>$rid]);DB::table('membership_campuses')->insert(['school_id'=>$sid,'membership_id'=>$mid,'campus_id'=>$cid]);$session=DB::table('academic_sessions')->insertGetId(['school_id'=>$sid,'name'=>'2026-27','starts_on'=>'2026-04-01','ends_on'=>'2027-03-31','status'=>'active']);$class=DB::table('classes')->insertGetId(['school_id'=>$sid,'name'=>'Class 1','position'=>1]);$section=DB::table('sections')->insertGetId(['school_id'=>$sid,'campus_id'=>$cid,'academic_session_id'=>$session,'class_id'=>$class,'name'=>'A','capacity'=>20]);$student=DB::table('students')->insertGetId(['school_id'=>$sid,'admission_no'=>'ATT-1','first_name'=>'Ali','admitted_on'=>'2026-10-01','status'=>'active']);$enrollment=DB::table('enrollments')->insertGetId(['school_id'=>$sid,'student_id'=>$student,'section_id'=>$section,'starts_on'=>'2026-10-01','status'=>'active']);$staff=null;if($role==='teacher'){$staff=DB::table('staff_profiles')->insertGetId(['school_id'=>$sid,'membership_id'=>$mid,'employee_no'=>'T1','status'=>'active']);DB::table('teacher_assignments')->insert(['school_id'=>$sid,'staff_profile_id'=>$staff,'section_id'=>$section,'is_class_teacher'=>true]);}return compact('sid','cid','user','mid','rid','session','class','section','student','enrollment','staff');
 }
 private function login(array $f):void{$this->actingAs($f['user'])->withSession(['school_id'=>$f['sid']]);}
 private function data(array $f,string $date='2026-10-17',int $revision=0,string $action='submit'):array{return ['section_id'=>$f['section'],'date'=>$date,'revision'=>$revision,'action'=>$action,'records'=>[['enrollment_id'=>$f['enrollment'],'status'=>'present','remarks'=>null]]];}
 private function day(array $f,string $date='2026-10-17'){return $this->getJson('/app-api/attendance/day?section_id='.$f['section'].'&date='.$date);}
 public function test_draft_submit_and_reasoned_corrections_keep_revision_and_audit_history():void {
  $f=$this->fixture();$this->login($f);$this->day($f)->assertOk()->assertJsonPath('roster.0.status',null)->assertJsonPath('revision',0);$d=$this->data($f,'2026-10-17',0,'draft');$this->postJson('/app-api/attendance/day',$d)->assertOk()->assertJsonPath('revision',1);$rid=DB::table('attendance_records')->value('id');$d['revision']=1;$d['action']='submit';$this->postJson('/app-api/attendance/day',$d)->assertOk()->assertJsonPath('revision',2);$d['revision']=2;$d['records'][0]['status']='absent';$this->postJson('/app-api/attendance/day',$d)->assertUnprocessable();$d['reason']='Corrected after class review';$this->postJson('/app-api/attendance/day',$d)->assertOk()->assertJsonPath('revision',3);$this->assertDatabaseHas('attendance_records',['id'=>$rid,'status'=>'absent']);$history=$this->getJson('/app-api/attendance/history?section_id='.$f['section'].'&date=2026-10-17')->assertOk()->assertJsonCount(3,'data');$history->assertJsonPath('data.0.changes.before.0.status','present')->assertJsonPath('data.0.changes.after.0.status','absent')->assertJsonPath('data.0.actor_name',$f['user']->name);
  $d['revision']=3;$this->postJson('/app-api/attendance/day',$d)->assertJsonPath('revision',3)->assertJsonPath('message','No attendance changes to save.');$this->assertDatabaseCount('audit_logs',3);$this->artisan('database:verify')->assertSuccessful();
 }
 public function test_stale_tabs_cannot_overwrite_a_newer_register_and_missing_marks_cannot_submit():void {
  $f=$this->fixture();$this->login($f);$d=$this->data($f);$d['records'][0]['status']=null;$this->postJson('/app-api/attendance/day',$d)->assertUnprocessable();$this->postJson('/app-api/attendance/day',$this->data($f))->assertOk();$d=$this->data($f);$d['reason']='Trying an older tab';$d['records'][0]['status']='absent';$this->postJson('/app-api/attendance/day',$d)->assertUnprocessable();$this->assertDatabaseHas('attendance_records',['status'=>'present']);$this->assertDatabaseCount('attendance_sessions',1);
 }
 public function test_roster_uses_enrollment_dates_including_withdrawn_students_and_rejects_forged_rows():void {
  $f=$this->fixture();$this->login($f);DB::table('students')->where('id',$f['student'])->update(['status'=>'withdrawn']);DB::table('enrollments')->where('id',$f['enrollment'])->update(['ends_on'=>'2026-10-15','status'=>'withdrawn']);$this->day($f,'2026-10-14')->assertJsonCount(1,'roster');$this->day($f,'2026-10-17')->assertJsonCount(0,'roster');$d=$this->data($f);$this->postJson('/app-api/attendance/day',$d)->assertUnprocessable();$this->postJson('/app-api/attendance/day',$this->data($f,'2026-10-14'))->assertOk();$this->day($f,'2026-10-18')->assertUnprocessable();$this->day($f,'2026-03-31')->assertUnprocessable();$this->day($f,'2026-09-30')->assertJsonCount(0,'roster');
 }
 public function test_teachers_only_access_their_class_teacher_sections_and_cannot_correct_submission():void {
  $f=$this->fixture('T','teacher');$this->login($f);$this->getJson('/app-api/attendance/setup')->assertJsonCount(1,'sections')->assertJsonPath('oversee',false);$this->postJson('/app-api/attendance/day',$this->data($f))->assertOk();$d=$this->data($f,'2026-10-17',1);$d['reason']='Teacher correction attempt';$d['records'][0]['status']='late';$this->postJson('/app-api/attendance/day',$d)->assertForbidden();DB::table('teacher_assignments')->where('staff_profile_id',$f['staff'])->update(['is_class_teacher'=>false]);$this->day($f)->assertNotFound();$this->getJson('/app-api/attendance/setup')->assertJsonCount(0,'sections');
 }
 public function test_school_campus_and_permission_overrides_restrict_attendance():void {
  $a=$this->fixture();$b=$this->fixture('B');$this->login($a);$this->day($b)->assertNotFound();$this->postJson('/app-api/attendance/day',$this->data($b))->assertNotFound();$this->getJson('/app-api/attendance/report?section_id='.$b['section'].'&month=2026-10')->assertNotFound();
  $this->login($a);$rid=DB::table('roles')->where('name','principal')->value('id');DB::table('membership_roles')->where('membership_id',$a['mid'])->update(['role_id'=>$rid]);DB::table('membership_campuses')->where('membership_id',$a['mid'])->delete();$this->day($a)->assertNotFound();DB::table('membership_campuses')->insert(['school_id'=>$a['sid'],'membership_id'=>$a['mid'],'campus_id'=>$a['cid']]);foreach(['attendance.manage','attendance.correct'] as $name)DB::table('school_role_permissions')->insert(['school_id'=>$a['sid'],'role_id'=>$rid,'permission_id'=>DB::table('permissions')->where('name',$name)->value('id'),'enabled'=>false]);$this->day($a)->assertOk()->assertJsonPath('can_mark',false);$this->postJson('/app-api/attendance/day',$this->data($a))->assertForbidden();
 }
 public function test_monthly_report_excludes_draft_and_day_off_from_percentage_and_never_invents_absences():void {
  $f=$this->fixture();$this->login($f);$s=DB::table('students')->insertGetId(['school_id'=>$f['sid'],'admission_no'=>'ATT-2','first_name'=>'Sara','admitted_on'=>'2026-10-01','status'=>'withdrawn']);$e=DB::table('enrollments')->insertGetId(['school_id'=>$f['sid'],'student_id'=>$s,'section_id'=>$f['section'],'starts_on'=>'2026-10-01','ends_on'=>'2026-10-15','status'=>'withdrawn']);
  $d=$this->data($f,'2026-10-01');$d['records'][]=['enrollment_id'=>$e,'status'=>'absent'];$this->postJson('/app-api/attendance/day',$d)->assertOk();$draft=$this->data($f,'2026-10-02',0,'draft');$this->postJson('/app-api/attendance/day',$draft)->assertOk();$this->postJson('/app-api/attendance/day',['section_id'=>$f['section'],'date'=>'2026-10-03','revision'=>0,'action'=>'day_off','reason'=>'School annual holiday','records'=>[]])->assertOk();$d['date']='2026-10-04';$d['records'][0]['status']='late';$d['records'][1]['status']='leave';$this->postJson('/app-api/attendance/day',$d)->assertOk();
  $this->getJson('/app-api/attendance/report?section_id='.$f['section'].'&month=2026-10')->assertOk()->assertJsonPath('summary.submitted',2)->assertJsonPath('summary.draft',1)->assertJsonPath('summary.non_instructional',1)->assertJsonPath('rows.0.counts.present',1)->assertJsonPath('rows.0.counts.late',1)->assertJsonPath('rows.0.counts.absent',0)->assertJsonPath('rows.0.marked_days',2)->assertJsonPath('rows.0.attendance_percent',100)->assertJsonPath('rows.1.counts.absent',1)->assertJsonPath('rows.1.counts.leave',1)->assertJsonPath('rows.1.attendance_percent',0)->assertJsonPath('rows.1.cells.16.state','not_enrolled');$this->getJson('/app-api/attendance/overview?date=2026-10-04')->assertJsonPath('sections.0.counts.late',1)->assertJsonPath('sections.0.counts.leave',1);$this->getJson('/app-api/attendance/report?section_id='.$f['section'].'&month=2027-10')->assertUnprocessable();
 }
 public function test_no_class_conversion_and_replacement_are_reasoned_audited_corrections():void {
  $f=$this->fixture();$this->login($f);$this->postJson('/app-api/attendance/day',$this->data($f))->assertOk();$off=['section_id'=>$f['section'],'date'=>'2026-10-17','revision'=>1,'action'=>'day_off','records'=>[]];$this->postJson('/app-api/attendance/day',$off)->assertUnprocessable();$off['reason']='Unexpected school closure';$this->postJson('/app-api/attendance/day',$off)->assertOk();$this->assertDatabaseCount('attendance_records',0);$this->day($f)->assertJsonPath('session.status','non_instructional');$d=$this->data($f,'2026-10-17',2);$d['reason']='Closure entered for wrong section';$this->postJson('/app-api/attendance/day',$d)->assertOk();$this->assertDatabaseCount('attendance_records',1);$this->getJson('/app-api/attendance/history?section_id='.$f['section'].'&date=2026-10-17')->assertJsonPath('data.1.changes.before.0.status','present')->assertJsonPath('data.1.changes.after_status','non_instructional');
 }
 public function test_saved_roster_mismatch_and_duplicate_enrollment_are_not_silently_deleted():void {
  $f=$this->fixture();$this->login($f);$this->postJson('/app-api/attendance/day',$this->data($f))->assertOk();DB::table('enrollments')->where('id',$f['enrollment'])->update(['ends_on'=>'2026-10-16']);$d=$this->data($f,'2026-10-17',1);$d['reason']='Attempting changed enrollment';$this->postJson('/app-api/attendance/day',$d)->assertUnprocessable();$this->assertDatabaseCount('attendance_records',1);$this->getJson('/app-api/attendance/report?section_id='.$f['section'].'&month=2026-10')->assertJsonPath('roster_warnings',1);DB::table('enrollments')->where('id',$f['enrollment'])->update(['ends_on'=>null]);DB::table('enrollments')->insert(['school_id'=>$f['sid'],'student_id'=>$f['student'],'section_id'=>$f['section'],'starts_on'=>'2026-10-05','status'=>'active']);$this->day($f)->assertUnprocessable();
 }
 public function test_guest_provider_and_unlicensed_module_have_no_attendance_access():void {
  $this->getJson('/app-api/attendance/setup')->assertUnauthorized();$f=$this->fixture();$this->login($f);$license=\App\Services\LicenseService::ensure($f['sid']);DB::table('subscriptions')->insert(['school_id'=>$f['sid'],'plan_id'=>DB::table('plans')->value('id'),'license_id'=>$license->id,'kind'=>'paid','student_limit'=>1000,'campus_limit'=>2,'modules'=>json_encode(['fees']),'package_name'=>'Fees only','starts_on'=>'2026-01-01','ends_on'=>'2027-12-31','price'=>'100','status'=>'active']);$this->getJson('/app-api/attendance/setup')->assertForbidden();$provider=User::factory()->create();DB::table('platform_admins')->insert(['user_id'=>$provider->id,'active'=>true]);$this->actingAs($provider)->withSession(['school_id'=>$f['sid']])->getJson('/app-api/attendance/setup')->assertForbidden();
 }
 public function test_closed_sessions_require_an_explicit_reason_and_correction_permission():void {
  $f=$this->fixture();$this->login($f);DB::table('academic_sessions')->where('id',$f['session'])->update(['status'=>'closed']);$this->day($f)->assertJsonPath('requires_correction',true);$d=$this->data($f);$this->postJson('/app-api/attendance/day',$d)->assertUnprocessable();$d['reason']='Authorized historical register backfill';$this->postJson('/app-api/attendance/day',$d)->assertOk();
 }
}
